  | {
      status?: "failed";
      dateRange?: {
        from: Date;
        to: Date;
      };
    };

export interface ITransactionModule {
  create(transaction: TransactionInput): Promise<ITransaction>;
  list(userId: TUserId): Promise<ITransaction[]>;
  query(query: TTransactionQuery, userId: TUserId): Promise<ITransaction[]>;
};

